add_action( 'template_redirect', 'perfectpixel_empty_cart_redirect' );
add_action( 'wp_footer', 'perfectpixel_empty_cart_redirect_script' );

function perfectpixel_empty_cart_redirect_url() {
	$url = trim( '{{empty_cart_redirect_url}}' );
	if ( '' === $url ) {
		return wc_get_page_permalink( 'shop' );
	}
	return 0 === strpos( $url, '/' ) ? home_url( $url ) : $url;
}

function perfectpixel_empty_cart_redirect() {
	if ( function_exists( 'is_cart' ) && is_cart() && WC()->cart && WC()->cart->is_empty() ) {
		wp_safe_redirect( perfectpixel_empty_cart_redirect_url() );
		exit;
	}
}

// When the last item is removed on the cart page (AJAX), reload so the redirect happens.
function perfectpixel_empty_cart_redirect_script() {
	if ( ! function_exists( 'is_cart' ) || ! is_cart() ) {
		return;
	}
	echo '<script>jQuery( document.body ).on( "wc_cart_emptied", function () { window.location.href = ' . wp_json_encode( perfectpixel_empty_cart_redirect_url() ) . '; } );</script>';
}
